#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <microhttpd.h>
#include <curl/curl.h>
#include <openssl/hmac.h>
#include <openssl/rand.h>
#include <time.h>

#define MAX_CHALLENGE_LEN 32
#define SERVICE_PORT 8443
#define BACKEND_VERIFY_URL "http://dc.internal:9090/ntlm/verify"

typedef struct {
    unsigned char server_challenge[MAX_CHALLENGE_LEN];
    time_t issued_at;
    int state; /* 0=init, 1=challenge_sent, 2=authenticated */
    char client_ip[64];
    unsigned char channel_binding[32];
} AuthSession;

static AuthSession sessions[256];
static int session_count = 0;

static int generate_challenge(unsigned char *buf, size_t len) {
    /* Check RAND_bytes result: on failure the challenge would be
     * predictable/uninitialized, undermining the security guarantee. */
    if (RAND_bytes(buf, (int)len) != 1) {
        return -1;
    }
    return 0;
}

static int extract_ntlmv2_response(const char *auth_header, unsigned char *nt_response, size_t *resp_len) {
    if (!auth_header) return -1;

    /* Validate we have enough header to safely locate NTLMSSP. */
    size_t header_len = strlen(auth_header);

    const char *resp_start = strstr(auth_header, "NTLMSSP");
    if (!resp_start) return -1;

    /* Offset of resp_start within the header buffer. */
    size_t base = (size_t)(resp_start - auth_header);
    /* Bytes available from resp_start to end of header buffer. */
    size_t avail = header_len - base;

    /* Need at least through offsets 24 + 4 (nt_offset field) to read fields. */
    if (avail < 28) return -1;

    unsigned int msg_type = *(unsigned int*)(resp_start + 8);
    if (msg_type != 3) return -1;

    /* Extract NtChallengeResponse from Type 3 at standard offset */
    unsigned short nt_len = *(unsigned short*)(resp_start + 22);
    unsigned int nt_offset = *(unsigned int*)(resp_start + 24);

    if (nt_len > 256 || nt_offset > 512) return -1;

    /* Ensure the [nt_offset, nt_offset+nt_len) region is fully contained
     * within the header buffer to prevent an out-of-bounds read. */
    if ((size_t)nt_offset > avail) return -1;
    if ((size_t)nt_len > avail - (size_t)nt_offset) return -1;

    memcpy(nt_response, resp_start + nt_offset, nt_len);
    *resp_len = nt_len;
    return 0;
}

static int verify_ntlm_locally(const unsigned char *nt_response, size_t resp_len,
                                const unsigned char *server_challenge, AuthSession *sess) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    char response[512] = {0};
    char post_data[2048];

    /* Send challenge + response to DC for server-side verification.
     * Critically: we send OUR challenge that WE generated, not the client's claim.
     * The DC verifies the response was computed against this specific challenge. */
    char challenge_hex[17] = {0};
    for (int i = 0; i < 8; i++)
        snprintf(challenge_hex + i*2, 3, "%02x", server_challenge[i]);

    char response_hex[513] = {0};
    for (size_t i = 0; i < resp_len && i < 256; i++)
        snprintf(response_hex + i*2, 3, "%02x", nt_response[i]);

    snprintf(post_data, sizeof(post_data),
             "{\"challenge\":\"%s\",\"response\":\"%s\"}",
             challenge_hex, response_hex);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, BACKEND_VERIFY_URL);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);

    /* Write callback inline */
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, 
        (size_t(*)(void*,size_t,size_t,void*))({size_t fn(void *p, size_t s, size_t n, void *u){size_t t=s*n;memcpy(u,p,t<512?t:512);return t;}&fn;}));
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) return -1;
    /* DC returns 200 only if response matches challenge+password_hash */
    return (http_code == 200) ? 0 : -1;
}

static enum MHD_Result handle_request(
    void *cls, struct MHD_Connection *conn,
    const char *url, const char *method,
    const char *version, const char *upload_data,
    size_t *upload_data_size, void **con_cls)
{
    const char *auth = MHD_lookup_connection_value(conn, MHD_HEADER_KIND, "Authorization");
    struct MHD_Response *response;
    int ret;

    if (!auth) {
        AuthSession *sess = &sessions[session_count % 256];
        if (generate_challenge(sess->server_challenge, 8) != 0) {
            response = MHD_create_response_from_buffer(21, "Internal server error", MHD_RESPMEM_PERSISTENT);
            ret = MHD_queue_response(conn, MHD_HTTP_INTERNAL_SERVER_ERROR, response);
            MHD_destroy_response(response);
            return ret;
        }
        sess->issued_at = time(NULL);
        sess->state = 1;
        session_count++;

        char challenge_hdr[256];
        snprintf(challenge_hdr, sizeof(challenge_hdr),
                 "NTLM TlRMTVNTUAACAAAAAAAAAAAAAAAGAoEA%s",
                 (char*)sess->server_challenge);

        response = MHD_create_response_from_buffer(0, "", MHD_RESPMEM_PERSISTENT);
        MHD_add_response_header(response, "WWW-Authenticate", challenge_hdr);
        ret = MHD_queue_response(conn, MHD_HTTP_UNAUTHORIZED, response);
        MHD_destroy_response(response);
        return ret;
    }

    if (strncmp(auth, "NTLM ", 5) == 0) {
        AuthSession *sess = &sessions[(session_count - 1) % 256];

        if (time(NULL) - sess->issued_at > 30) {
            response = MHD_create_response_from_buffer(17, "Challenge expired", MHD_RESPMEM_PERSISTENT);
            ret = MHD_queue_response(conn, MHD_HTTP_UNAUTHORIZED, response);
            MHD_destroy_response(response);
            return ret;
        }

        /* Extract and verify locally - do NOT forward raw auth header */
        unsigned char nt_response[256];
        size_t resp_len = 0;

        if (extract_ntlmv2_response(auth, nt_response, &resp_len) != 0) {
            response = MHD_create_response_from_buffer(12, "Parse failed", MHD_RESPMEM_PERSISTENT);
            ret = MHD_queue_response(conn, MHD_HTTP_BAD_REQUEST, response);
            MHD_destroy_response(response);
            return ret;
        }

        int auth_result = verify_ntlm_locally(nt_response, resp_len,
                                               sess->server_challenge, sess);

        if (auth_result == 0) {
            sess->state = 2;
            const char *body = "{\"status\": \"authenticated\", \"access\": \"granted\"}";
            response = MHD_create_response_from_buffer(strlen(body), (void*)body, MHD_RESPMEM_PERSISTENT);
            MHD_add_response_header(response, "Content-Type", "application/json");
            ret = MHD_queue_response(conn, MHD_HTTP_OK, response);
        } else {
            const char *body = "{\"status\": \"auth_failed\"}";
            response = MHD_create_response_from_buffer(strlen(body), (void*)body, MHD_RESPMEM_PERSISTENT);
            ret = MHD_queue_response(conn, MHD_HTTP_FORBIDDEN, response);
        }
        MHD_destroy_response(response);
        return ret;
    }

    response = MHD_create_response_from_buffer(11, "Bad Request", MHD_RESPMEM_PERSISTENT);
    ret = MHD_queue_response(conn, MHD_HTTP_BAD_REQUEST, response);
    MHD_destroy_response(response);
    return ret;
}

int main(int argc, char **argv) {
    struct MHD_Daemon *daemon;

    daemon = MHD_start_daemon(
        MHD_USE_THREAD_PER_CONNECTION,
        SERVICE_PORT, NULL, NULL,
        &handle_request, NULL,
        MHD_OPTION_END);

    if (!daemon) {
        fprintf(stderr, "Failed to start server\n");
        return 1;
    }

    printf("NTLM auth service running on port %d\n", SERVICE_PORT);
    getchar();
    MHD_stop_daemon(daemon);
    return 0;
}
